const query = $json.query && typeof $json.query === 'object' ? $json.query : {};
const mode = String(query['hub.mode'] || '').trim();
const receivedToken = String(query['hub.verify_token'] || '').trim();
const challenge = String(query['hub.challenge'] || '').trim();

let expectedToken = '';
try {
  expectedToken = String($env.WHATSAPP_WEBHOOK_VERIFY_TOKEN || '').trim();
} catch (error) {
  expectedToken = '';
}

const valid = Boolean(
  expectedToken &&
  mode === 'subscribe' &&
  receivedToken === expectedToken &&
  challenge
);

return [{
  json: {
    valid,
    challenge,
    responseBody: valid
      ? challenge
      : {
          success: false,
          error: expectedToken
            ? 'Verificação do webhook recusada.'
            : 'WHATSAPP_WEBHOOK_VERIFY_TOKEN não foi configurado no servidor do n8n.'
        }
  }
}];

const headers = $json.headers && typeof $json.headers === 'object' ? $json.headers : {};
const body = $json.body && typeof $json.body === 'object' ? $json.body : {};
const signature = String(
  headers['x-hub-signature-256'] ||
  headers['X-Hub-Signature-256'] ||
  ''
).trim();

let appSecret = '';
try {
  appSecret = String($env.WHATSAPP_APP_SECRET || '').trim();
} catch (error) {
  appSecret = '';
}

const result = {
  signatureValid: false,
  signatureError: null,
  body,
  headers,
  receivedAt: new Date().toISOString()
};

if (!appSecret) {
  result.signatureError = 'WHATSAPP_APP_SECRET não foi configurado no servidor do n8n.';
  return [{ json: result }];
}

if (!signature.startsWith('sha256=')) {
  result.signatureError = 'Cabeçalho x-hub-signature-256 ausente ou inválido.';
  return [{ json: result }];
}

const rawBase64 = $binary?.data?.data || '';
if (!rawBase64) {
  result.signatureError = 'O corpo bruto da requisição não foi disponibilizado pelo Webhook node.';
  return [{ json: result }];
}

try {
  const rawBody = Buffer.from(rawBase64, 'base64');
  let expectedHex = '';

  if (globalThis.crypto?.subtle) {
    const key = await globalThis.crypto.subtle.importKey(
      'raw',
      new TextEncoder().encode(appSecret),
      { name: 'HMAC', hash: 'SHA-256' },
      false,
      ['sign']
    );
    const mac = await globalThis.crypto.subtle.sign('HMAC', key, rawBody);
    expectedHex = Buffer.from(mac).toString('hex');
  } else {
    const { createHmac } = require('crypto');
    expectedHex = createHmac('sha256', appSecret).update(rawBody).digest('hex');
  }

  const expected = `sha256=${expectedHex}`;
  let mismatch = expected.length ^ signature.length;
  const maxLength = Math.max(expected.length, signature.length);

  for (let index = 0; index < maxLength; index += 1) {
    mismatch |= (expected.charCodeAt(index) || 0) ^ (signature.charCodeAt(index) || 0);
  }

  result.signatureValid = mismatch === 0;
  if (!result.signatureValid) {
    result.signatureError = 'Assinatura HMAC inválida.';
  }
} catch (error) {
  result.signatureError = `Não foi possível validar a assinatura: ${error.message || String(error)}`;
}

return [{ json: result }];

const payload = $json.body && typeof $json.body === 'object' ? $json.body : {};
const entries = Array.isArray(payload.entry) ? payload.entry : [];
const receivedAt = $json.receivedAt || new Date().toISOString();
const normalized = [];

const pushEvent = ({
  eventType,
  destination,
  field,
  entryId,
  value,
  message = null,
  status = null,
  contact = null,
  extra = {}
}) => {
  const metadata = value?.metadata && typeof value.metadata === 'object' ? value.metadata : {};
  const messageId = String(message?.id || status?.id || '').trim() || null;
  const eventKey = [
    eventType,
    entryId || 'no-entry',
    metadata.phone_number_id || 'no-phone-number',
    messageId || field || 'no-id'
  ].join(':');

  normalized.push({
    json: {
      source: 'meta-whatsapp-cloud-api',
      eventType,
      destination,
      eventKey,
      field,
      receivedAt,
      wabaId: entryId || null,
      phoneNumberId: metadata.phone_number_id || null,
      displayPhoneNumber: metadata.display_phone_number || null,
      messageId,
      senderPhone: message?.from || contact?.wa_id || null,
      recipientPhone: status?.recipient_id || null,
      message,
      status,
      contacts: contact ? [contact] : [],
      coexistencePayload: extra.coexistencePayload || null,
      rawValue: value
    }
  });
};

for (const entry of entries) {
  const entryId = String(entry?.id || '').trim() || null;
  const changes = Array.isArray(entry?.changes) ? entry.changes : [];

  for (const change of changes) {
    const field = String(change?.field || 'unknown').trim() || 'unknown';
    const value = change?.value && typeof change.value === 'object' ? change.value : {};

    if (field === 'messages') {
      const messages = Array.isArray(value.messages) ? value.messages : [];
      const statuses = Array.isArray(value.statuses) ? value.statuses : [];
      const contacts = Array.isArray(value.contacts) ? value.contacts : [];

      for (const message of messages) {
        const contact = contacts.find((item) => item?.wa_id === message?.from) || contacts[0] || null;
        pushEvent({
          eventType: 'inbound_message',
          destination: 'chatbot',
          field,
          entryId,
          value,
          message,
          contact
        });
      }

      for (const status of statuses) {
        pushEvent({
          eventType: 'message_status',
          destination: 'platform',
          field,
          entryId,
          value,
          status
        });
      }

      if (!messages.length && !statuses.length) {
        pushEvent({
          eventType: 'messages_event_without_message_or_status',
          destination: 'log',
          field,
          entryId,
          value
        });
      }

      continue;
    }

    if (field === 'smb_message_echoes') {
      pushEvent({
        eventType: 'business_app_echo',
        destination: 'platform',
        field,
        entryId,
        value,
        extra: { coexistencePayload: value }
      });
      continue;
    }

    if (field === 'history' || field === 'smb_app_state_sync') {
      pushEvent({
        eventType: 'coexistence_sync',
        destination: 'platform',
        field,
        entryId,
        value,
        extra: { coexistencePayload: value }
      });
      continue;
    }

    pushEvent({
      eventType: 'unclassified_whatsapp_event',
      destination: 'log',
      field,
      entryId,
      value
    });
  }
}

if (!normalized.length) {
  normalized.push({
    json: {
      source: 'meta-whatsapp-cloud-api',
      eventType: 'invalid_or_empty_payload',
      destination: 'log',
      eventKey: `invalid:${Date.now()}`,
      field: null,
      receivedAt,
      wabaId: null,
      phoneNumberId: null,
      messageId: null,
      rawValue: payload
    }
  });
}

return normalized;

let destinationUrl = '';
let destinationToken = '';

try {
  if ($json.destination === 'chatbot') {
    destinationUrl = String($env.WHATSAPP_CHATBOT_WEBHOOK_URL || '').trim();
    destinationToken = String($env.WHATSAPP_CHATBOT_ROUTER_TOKEN || '').trim();
  } else if ($json.destination === 'platform') {
    destinationUrl = String($env.EVOLUCAO_CLINICA_WHATSAPP_EVENTS_URL || '').trim();
    destinationToken = String($env.EVOLUCAO_CLINICA_WHATSAPP_EVENTS_TOKEN || '').trim();
  }
} catch (error) {
  destinationUrl = '';
  destinationToken = '';
}

return [{
  json: {
    ...$json,
    destinationUrl,
    destinationToken,
    destinationConfigured: /^https?:\/\//i.test(destinationUrl)
  }
}];
